  const ruler = new THREE.Group(); ruler.position.set(0, 0, 0.7);   // just behind the user
  ruler.add(new THREE.Mesh(new THREE.CylinderGeometry(0.01, 0.01, 2.2, 6), new THREE.MeshBasicMaterial({ color:0xffffff })).translateY(1.1));
  for (let h = 0; h <= 2.2001; h += 0.1){ const big = Math.round(h*10) % 5 === 0; const t = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.012, big?0.16:0.08), new THREE.MeshBasicMaterial({ color: big?0xffc53d:0xffffff })); t.position.set(0, h, 0); ruler.add(t); }
  for (const [k, y, dz] of [['0.5', 0.5, 0.3], ['1.0', 1.0, 0.3], ['1.5', 1.5, 0.3], ['2.0', 2.0, 0.3], ['eye', H.eye, -0.3], ['waist', H.waist, -0.3], ['chest', H.chest, -0.3]]){
    const l = label(k, { at:[0, y, 0.7 + dz], capHeight:0.05, bg:false, color:'#ffc53d' }); tracked.delete(l); scene.remove(l); l.position.set(0, y, 0.7 + dz); debugGroup.add(l);
  }
