if (DEBUG) buildDebug();

// stations: places the user is expected to stand (besides the start). Each is [x, z] or [x, z, facingDeg].
// The audit judges every object from the NEAREST station, so multi-area scenes (a course, a gallery) get sensible numbers.
const stations = [];
function bearingOf(v){ // from the nearest station's eye: azimuth (+right), elevation, degrees
  let best = null;
  for (const st of [[0, 0, 0], ...stations]){
    const eye = new THREE.Vector3(st[0], H.eye, st[1]); const d = v.clone().sub(eye);
    const facing = THREE.MathUtils.degToRad(st[2] ?? 0);   // 0 = facing -Z
    const fx = d.x * Math.cos(facing) + d.z * Math.sin(facing), fz = -d.x * Math.sin(facing) + d.z * Math.cos(facing);
    const r = { az: THREE.MathUtils.radToDeg(Math.atan2(fx, -fz)), el: THREE.MathUtils.radToDeg(Math.atan2(d.y, Math.hypot(d.x, d.z))), dist: d.length(), station: st };
    if (!best || r.dist < best.dist) best = r;
  }
  return best;
}
// ---------- on-screen audit panel (?debug): the numbers a student pastes back when something looks wrong ----------
function auditReportText(r){
  const lines = [`XR audit — stature ${r.stature_m} m, eye ${r.eye_m} m, reach ${r.reach_m} m` + (r.stations ? `, judged from the nearest of ${r.stations} stations` : '')];
  for (const o of r.objects) lines.push(`${o.name} [${o.kind}] dist ${o.dist_m} m, az ${o.azimuth_deg}°, el ${o.elevation_deg}°, size ${o.size_m.join('×')} m, ${o.angular_deg}° wide` + (o.text ? `, text "${o.text.text.replace(/\n/g, ' / ')}" cap ${o.text.capHeight_cm} cm` : '') + (o.flags.length ? ` — ${o.flags.join(', ')}` : ''));
  for (const e of r.errors) lines.push('ERROR ' + e); for (const w of r.warnings) lines.push('WARN ' + w); for (const n of r.notes) lines.push('note ' + n);
  const err = document.getElementById('err')?.textContent; if (err) lines.push('ON-SCREEN ERROR: ' + err);
  return lines.join('\n');
}
function showAuditPanel(r){
  const el = document.getElementById('audit'); if (!el) return;
  const esc = t => String(t).replace(/[&<>]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;' }[c]));
  const rows = r.objects.map(o => `<tr><td>${esc(o.name)}</td><td>${o.dist_m}</td><td>${o.azimuth_deg}°</td><td>${o.elevation_deg}°</td><td>${o.angular_deg}°</td><td>${esc(o.flags.join(' '))}</td></tr>`).join('');
  el.innerHTML = `<h3>Spatial audit · ${r.objects.length} objects · ${r.errors.length} errors · ${r.warnings.length} warnings</h3>
    ${r.errors.map(e => `<div class="err">✖ ${esc(e)}</div>`).join('')}${r.warnings.map(w => `<div class="warn">▲ ${esc(w)}</div>`).join('')}${r.notes.map(n => `<div class="note">· ${esc(n)}</div>`).join('')}
    <table><tr><th>object</th><th>dist</th><th>az</th><th>el</th><th>wide</th><th>flags</th></tr>${rows}</table>
    <button id="audit-copy">Copy report for Claude</button><button id="audit-hide">Hide</button>`;
  el.style.display = 'block';
  el.querySelector('#audit-hide').onclick = () => { el.style.display = 'none'; };
  el.querySelector('#audit-copy').onclick = async () => { const t = auditReportText(r); try { await navigator.clipboard.writeText(t); el.querySelector('#audit-copy').textContent = 'Copied ✓'; } catch { prompt('Copy this report:', t); } };
}
/** audit(): numeric spatial report of everything placed/labelled/interactive, from the start position. */
function audit(){
  const eye = eyePos(); const rows = []; const warnings = [], errors = [], notes = [];
  const boxes = [];
  // stations sanity: malformed entries warn; only stations away from the origin count for warning suppression
  const badStations = stations.filter(s => !Array.isArray(s) || s.length < 2 || s.length > 3 || s.some(v => typeof v !== 'number'));
  for (const s of badStations) warnings.push(`stations entry ${JSON.stringify(s)} is malformed — use [x, z] or [x, z, facingDeg]`);
  const awayStations = stations.filter(s => !badStations.includes(s) && Math.hypot(s[0], s[1]) > 0.5);
  for (const [obj, meta] of tracked){
    if (!obj.parent || obj.parent === debugGroup) continue;
    let root = obj; while (root.parent) root = root.parent;
    if (root !== scene && root !== rig){ warnings.push(`${obj.name} is not attached to the scene — it will never render (a shape.group() must be scene.add()ed or place()d before things go inside it)`); continue; }
    obj.updateWorldMatrix(true, true);
    const b = new THREE.Box3().setFromObject(obj, true); if (b.isEmpty()) continue;
    const c = b.getCenter(new THREE.Vector3()), s = b.getSize(new THREE.Vector3());
    const { az, el, dist } = bearingOf(c);
    let visNow = true; for (let o = obj; o; o = o.parent) if (o.visible === false){ visNow = false; break; }
    if (!visNow){                                    // hidden at audit time: only its text size still matters (it may be shown later)
      const L = obj.userData.label;
      if (L){ const actualArcmin = L.capHeight / (dist*ARCMIN);
        if (actualArcmin < TEXT_ARCMIN.MIN - 1) errors.push(`label "${L.text}" (hidden at start) reads at ${actualArcmin.toFixed(0)}' from here — below the ${TEXT_ARCMIN.MIN}' floor`); }
      continue;
    }
    const maxDim = Math.max(s.x, s.y, s.z);
    const angular = THREE.MathUtils.radToDeg(2*Math.atan((maxDim/2)/Math.max(dist, 1e-3)));
    const inView = Math.abs(az) <= 45 && el >= -35 && el <= 30;
    const flags = [];
    const r = { name: obj.name, kind: meta.kind, center: c.toArray().map(n => +n.toFixed(2)), size_m: s.toArray().map(n => +n.toFixed(2)),
                dist_m: +dist.toFixed(2), azimuth_deg: +az.toFixed(0), elevation_deg: +el.toFixed(0), angular_deg: +angular.toFixed(1), inStartView: inView, flags };
    if (b.min.y < -0.02){ flags.push('below-floor'); errors.push(`${obj.name} extends ${(-b.min.y).toFixed(2)} m below the floor`); }
    if (Math.hypot(c.x, c.z) > floorRadius){ flags.push('beyond-floor'); warnings.push(`${obj.name} is ${Math.hypot(c.x, c.z).toFixed(1)} m out — past the edge of the ${floorRadius} m floor`); }
    if (Math.abs(az) > 100 && !awayStations.length){ flags.push('behind-user'); warnings.push(`${obj.name} starts behind the user (azimuth ${az.toFixed(0)}°)`); }
    if ((meta.kind === 'interactive' || meta.kind === 'label') && Math.abs(az) > 60 && Math.abs(az) <= 100 && !awayStations.length){
      flags.push('far-off-view'); warnings.push(`${obj.name} sits at azimuth ${az.toFixed(0)}° — well outside the starting view, so the visitor may never find it; prefer 'ahead-left'/'ahead-right' (±35°) or add a station facing it`); }
    if (dist < 0.25){ flags.push('inside-head'); errors.push(`${obj.name} is ${dist.toFixed(2)} m from the eyes — inside the user's head`); }
    if (angular > 120){ flags.push('fills-view'); warnings.push(`${obj.name} spans ${angular.toFixed(0)}° — it fills the whole view`); }
    if (angular < 0.5){ flags.push('tiny'); warnings.push(`${obj.name} is only ${angular.toFixed(2)}° across — barely visible`); }
    if (meta.kind === 'interactive'){
      const h = interactables.get(obj);
      if (angular < 1.5){ flags.push('hard-to-point-at'); warnings.push(`${obj.name} is interactive but only ${angular.toFixed(1)}° across — hard to point at`); }
      if (h?.grab && h.grab !== 'hold' && dist > H.reach*1.7){ flags.push('grab-out-of-reach'); warnings.push(`${obj.name} is grabbable but ${dist.toFixed(2)} m away — beyond arm's reach, so it will hang at the end of the pointer ray instead of sitting in the hand; put it at 'reach' if it should feel hand-held`); }
    }
    if (obj.userData.label){
      const L = obj.userData.label; r.text = { text: L.text, capHeight_cm: +(L.capHeight*100).toFixed(1), arcmin: L.arcmin, sizedForDistance_m: +L.distance.toFixed(2) };
      r.size_m = [+obj.geometry.parameters.width.toFixed(2), +obj.geometry.parameters.height.toFixed(2), 0];
      const actualArcmin = L.capHeight / (dist*ARCMIN);
      if (actualArcmin < TEXT_ARCMIN.MIN - 1){ flags.push('illegible'); errors.push(`label "${L.text}" reads at ${actualArcmin.toFixed(0)}' from the start — below the ${TEXT_ARCMIN.MIN}' floor`); }
      if (dist < 0.5){ flags.push('too-close-to-focus'); warnings.push(`label "${L.text}" is ${dist.toFixed(2)} m away — closer than 0.5 m is hard to focus on`); }
      if (Math.abs(el) > 35){ flags.push('neck-strain'); warnings.push(`label "${L.text}" is ${el.toFixed(0)}° ${el>0?'above':'below'} eye level — needs a sustained head tilt`); }
    }
    boxes.push({ obj, b, kind: meta.kind }); rows.push(r);
  }
  const _related = (a, b) => { for (let o = a; o; o = o.parent) if (o === b) return true; for (let o = b; o; o = o.parent) if (o === a) return true; return false; };
  const _is = new THREE.Box3(), _iv = new THREE.Vector3();
  for (let i = 0; i < boxes.length; i++) for (let j = i+1; j < boxes.length; j++){
    const A = boxes[i], B = boxes[j];
    if (!A.b.intersectsBox(B.b) || _related(A.obj, B.obj)) continue;
    _is.copy(A.b).intersect(B.b); _is.getSize(_iv);
    const deep = [_iv.x, _iv.y, _iv.z].filter(v => v > 0.03).length >= 2;   // substantial overlap, not just touching edges
    const aL = A.kind === 'label', bL = B.kind === 'label';
    if (deep && aL && bL) warnings.push(`labels ${A.obj.name} and ${B.obj.name} overlap — their text collides. Space per item ≈ dist × angle between items: spread the row wider or move it to 'near'`);
    else if (deep && A.kind === 'interactive' && B.kind === 'interactive') warnings.push(`${A.obj.name} and ${B.obj.name} are overlapping interactive targets — pointing will hit the wrong one. Increase the angle between them or move the row further out`);
    else if (!aL && !bL) notes.push(`${A.obj.name} and ${B.obj.name} overlap (fine if intended)`);
  }
  if (rows.length && !rows.some(r => r.inStartView) && !awayStations.length) warnings.push('Nothing is inside the comfortable starting view (±45° horizontal, -35°..+30° vertical)');
  const report = { stature_m: H.stature, eye_m: H.eye, reach_m: H.reach, stations: stations.length, objects: rows, errors, warnings, notes };
  if (!HARNESS){ showAuditPanel(report); console.group('%cXR audit', 'font-weight:bold'); console.table(rows.map(({flags, text, ...r}) => ({ ...r, flags: flags.join(' '), text: text?.text ?? '' }))); errors.forEach(e => console.error(e)); warnings.forEach(w => console.warn(w)); notes.forEach(n => console.info(n)); console.groupEnd(); }
  return report;
}

// ---------- harness support (headless verification) ----------
let debugCamera = null;
function view(kind){   // switch the render camera: 'eye' | 'top' | 'side' | null (= back to the user's camera)
  debugGroup.visible = DEBUG && kind !== 'eye';
  if (kind === 'eye'){ const c = new THREE.PerspectiveCamera(80, innerWidth/innerHeight, 0.05, 200); c.position.copy(eyePos()); c.lookAt(0, H.eye, -1); debugCamera = c; }
  else if (kind === 'top'){ const c = new THREE.OrthographicCamera(-4, 4, 4*innerHeight/innerWidth, -4*innerHeight/innerWidth, 0.1, 200); c.position.set(0, 20, 0); c.up.set(0,0,-1); c.lookAt(0,0,0); debugCamera = c; }
  else if (kind === 'side'){ const a = innerWidth/innerHeight, hw = 2.5, hh = hw/a; const c = new THREE.OrthographicCamera(-hw, hw, hh, -hh, 0.1, 200); c.position.set(20, hh - 0.3, 0); c.lookAt(0, hh - 0.3, 0); debugCamera = c; }
  else debugCamera = null;
}

// ---------- main loop ----------
let content = { build: null, frame: null };
let lastT = performance.now()/1000, elapsed = 0;
function loop(){
  const now = performance.now()/1000, dt = Math.min(now - lastT, 0.1); lastT = now; elapsed += dt; const t = elapsed;
  desktopUpdate(dt);
  if (renderer.xr.isPresenting) handleThumbsticks();
  for (const p of pointers){
    if (p.isXR){ p.line.visible = renderer.xr.isPresenting; } if (p.isXR && !renderer.xr.isPresenting) continue; if (!p.isXR && renderer.xr.isPresenting){ p.hovered && (setGlow(p.hovered,false), p.hovered=null); continue; } updatePointer(p);
    if (p.held && p.holdOnly){                       // grab:'hold' handles get a per-frame drag with the pointer's current point
      const h = interactables.get(p.held);
      if (h?.drag){ pointerRay(p); h.drag(p.held, { point: raycaster.ray.at(p.holdDist, new THREE.Vector3()), pointer: p }); }
    }
  }
  const camPos = (debugCamera ?? camera).getWorldPosition(new THREE.Vector3());
  for (const b of billboards){ _bbv.setFromMatrixPosition(b.matrixWorld); b.lookAt(camPos.x, _bbv.y, camPos.z); }   // yaw-only: labels never roll
  if (DEBUG){ const mq = debugGroup.getObjectByName('mannequin'); if (mq) mq.visible = Math.hypot(camPos.x, camPos.z) > 0.6 || !!debugCamera; }   // don't stand inside the mannequin's head on desktop
  for (const a of anims) a(dt, t);
  try { content.frame?.(dt, t); } catch (e) { showError('frame(): ' + e.message); content.frame = null; }
  renderer.render(scene, debugCamera ?? camera);
}
let started = false;
function run(c = {}){
  if (started) return; started = true; content = c;
  const fontReady = Promise.race([Promise.all([document.fonts.load('600 32px Nunito'), document.fonts.load('800 32px Nunito')]), new Promise(r => setTimeout(r, 1500))]);
  fontReady.then(() => runNow(c));
}
function runNow(c){
  try { c.build?.(XR); } catch (e) { showError('build(): ' + e.message + '\n' + (e.stack||'').split('\n').slice(1,3).join('\n')); }
  if (DEBUG && !HARNESS) setTimeout(audit, 50);
  renderer.setAnimationLoop(loop);
  XR.ready = true;
}
setTimeout(() => { if (!started) showError('CONTENT block never called XR.run(...) — check for a syntax error in the CONTENT script.'); }, 2000);

/** ground({ color, grid:false }) — recolour the ground and optionally hide the 1 m grid. */
function ground(o = {}){
  if (o.color !== undefined){ groundMat.color.set(col(o.color)); scene.getObjectByName('grid-mask').material.color.set(col(o.color)); }
  if (o.grid !== undefined) grid.visible = !!o.grid;
  if (o.arrow !== undefined) scene.getObjectByName('ahead-arrow').visible = !!o.arrow;
  if (o.radius){ floorRadius = o.radius; floor.geometry.dispose(); floor.geometry = new THREE.RingGeometry(0.001, o.radius, 96, Math.ceil(o.radius * 3)); scene.getObjectByName('plain').geometry = new THREE.RingGeometry(o.radius, 120, 64, 12);
                 scene.getObjectByName('grid-mask').visible = false; }   // walkable (teleport) area radius in metres
}
/** hand('right'|'left') → that controller's pointer { object, hovered, held, ... } (object is the controller; add things to it to hold them). */
function hand(which){ return pointers.find(p => p.isXR && p.hand === which) ?? pointers.find(p => p.isXR); }

const XR = { THREE, scene, rig, camera, renderer, floor, grid, H, D, SZ, DIR, C, col, mat, shape, place, fit, spread, remove, label, interactive, tone, spin, bob,
             track, recalibrate, audit, view, run, eyePos, get pointers(){ return pointers; }, ready: false,
             get frame(){ return content.frame; }, set frame(fn){ content.frame = fn; },   // `XR.frame = fn` is a common guess — make it work
             get build(){ return content.build; }, set build(fn){ content.build = fn; },
             input, onButton, onController, button, teleportTo, ground, sky, hand, stations, auditReportText,
             _test: { updatePointer, selectStart: pointerSelectStart, selectEnd: pointerSelectEnd, snapTurn, interactables, tracked, handleGamepads: handleThumbsticks, teleMarker } };
window.XR = XR;
